// next.config.ts: cacheComponents: true
import { cacheLife, cacheTag, updateTag } from "next/cache";

// Igual para todo mundo: guardado em cache por horas
async function getPosts() {
  "use cache";
  cacheLife("hours");
  cacheTag("posts");
  return db.post.findMany();
}

// Depois de criar um post: expira o cache, a próxima leitura já vê o novo
async function createPost(formData) {
  "use server";
  await db.post.create({ data: { title: formData.get("title") } });
  updateTag("posts");
}

// Modelo anterior (sem cacheComponents):
// fetch(url, { next: { revalidate: 60 } })  → regenera a cada 60 s
// fetch(url, { cache: "no-store" })         → busca sempre
// revalidatePath("/posts")                  → invalida a página

export async function GET() {
  const products = await db.product.findMany();
  return Response.json(products);
}

export async function POST(request) {
  const data = await request.json();
  const created = await db.product.create({ data });
  return Response.json(created, { status: 201 });
}

import { revalidatePath } from "next/cache";

async function createProduct(formData) {
  "use server";
  const name = String(formData.get("name") ?? "").trim();
  if (!name) return;
  await db.product.create({ data: { name } });
  revalidatePath("/products");
}

export default function NewProduct() {
  return (
    <form action={createProduct}>
      <input name="name" />
      <button type="submit">Salvar</button>
    </form>
  );
}
